	LEVEL_33_HISTORY = "Tras un agotador enfrentamiento con Red Boy, seguimos avanzando hacia la Isla Tempestad. En cuanto pusimos un pie aquí, nubes cargadas de relámpagos y ráfagas feroces comenzaron a aullar en patrones extraños y retorcidos. Aun así, no tenemos otra opción: la isla contiene la única entrada al palacio de la Princesa. Prepárense... se avecina una tormenta.",
